import numpy as np


def construct():
    """Greedy baseline: scan the grid row-major, add every point that keeps the set
    isosceles-free (an apex check in exact integer arithmetic). Deterministic."""
    n = 64
    pts = []
    seen = [set() for _ in range(n * n)]  # seen[i]: squared distances from point i to the set

    def ok(p):
        d2s = set()
        for q in pts:
            d2 = (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2
            if d2 in d2s or d2 in seen[q[0] * n + q[1]]:
                return None
            d2s.add(d2)
        return d2s

    for x in range(n):
        for y in range(n):
            p = (x, y)
            d2s = ok(p)
            if d2s is not None:
                seen[p[0] * n + p[1]] = d2s
                for q in pts:
                    seen[q[0] * n + q[1]].add((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2)
                pts.append(p)
    return [list(p) for p in pts]

import random
import time

def construct():
    """
    Improved greedy-distance-tracking search for a large subset of the 64x64 grid
    such that for every chosen point p, the distances to all other chosen points are
    pairwise distinct (no isosceles at any pair of points with p as apex).
    Returns a list of [x, y] integer coordinates with 0 <= x, y <= 63.
    """

    n = 64
    all_pts = [(x, y) for x in range(n) for y in range(n)]

    # Time budget tuned for reliability; should finish quickly on typical runs
    TOTAL_TIME_SECONDS = 2.0
    t_start = time.time()

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx*dx + dy*dy

    best_pts = []
    best_size = 0

    # dist_sets[q] stores distances from q to all points currently in the set
    dist_sets = {}

    def can_add(p, pts, dist_sets):
        # Distances from p to existing pts must be all distinct
        dists_to_p = []
        for q in pts:
            d = dist2(p, q)
            if d in dists_to_p:
                return False
            dists_to_p.append(d)
            # For existing q, the distance d must not already appear in dist_sets[q]
            if d in dist_sets.get(q, set()):
                return False
        return True

    def add_point(p, pts, dist_sets):
        # Update structures after adding p
        new_dists = [dist2(p, q) for q in pts]
        for i, q in enumerate(pts):
            d = new_dists[i]
            dist_sets.setdefault(q, set()).add(d)
        dist_sets[p] = set(new_dists)
        pts.append(p)

    # Optional deterministic seed for reproducibility
    SEED = 123456789
    random.seed(SEED)

    # Start with a simple full-order list; use a small deterministic shuffle to diversify
    base_order = all_pts[:]
    random.shuffle(base_order)

    # Helper to greedily build a candidate from an order
    def build_from_order(order):
        pts = []
        # local copy of dist_sets to avoid mutating global during trial
        local_dist_sets = {}
        for p in order:
            if can_add(p, pts, {**local_dist_sets}):
                add_point(p, pts, local_dist_sets)
        return pts

    # Main loop with time budget
    while time.time() - t_start < TOTAL_TIME_SECONDS:
        order = base_order[:]
        r = random.random()

        # Strategy mix: slight bias between full shuffle and prefix-stable shuffle
        if r < 0.6:
            random.shuffle(order)
        else:
            head_len = max(1, int(0.22 * len(order)))
            head = order[:head_len]
            tail = order[head_len:]
            random.shuffle(tail)
            order = head + tail

        pts = build_from_order(order)

        if len(pts) > best_size:
            best_size = len(pts)
            best_pts = pts
            if best_size >= 112:
                break

        # Local perturbation: try extending best set with a shuffled tail
        if best_pts:
            subset = best_pts[:]
            random.shuffle(subset)
            cut = max(1, int(0.2 * len(subset)))
            partial = subset[:-cut] if len(subset) > cut else subset
            if partial:
                order2 = partial + all_pts
                pts2 = build_from_order(order2)
                if len(pts2) > best_size:
                    best_size = len(pts2)
                    best_pts = pts2
                    if best_size >= 112:
                        break

    if not best_pts:
        return []

    # Defensively normalize output: ensure proper shape and types
    cleaned = []
    seen = set()
    for p in best_pts:
        if not (isinstance(p, (list, tuple)) and len(p) == 2):
            continue
        x, y = int(p[0]), int(p[1])
        if 0 <= x < n and 0 <= y < n:
            if (x, y) not in seen:
                cleaned.append([x, y])
                seen.add((x, y))

    # Final quick validation: ensure pairwise distance property holds
    def validate(lst):
        m = len(lst)
        for i in range(m):
            for j in range(i+1, m):
                if lst[i] == lst[j]:
                    return False
        # Check no isosceles about any apex
        for i in range(m):
            pi = lst[i]
            dists = {}
            for j in range(m):
                if i == j:
                    continue
                dj = (pi[0]-lst[j][0])**2 + (pi[1]-lst[j][1])**2
                if dj in dists:
                    return False
                dists[dj] = j
        return True

    if not cleaned or not validate(cleaned):
        # Fallback: return the best valid subset we can assemble with a lightweight check
        # Start from empty and greedily add ensuring validity
        final = []
        dist_sets_final = {}
        for p in best_pts:
            if all(p != q for q in final):
                ok = True
                dists_to_p = []
                for q in final:
                    d = dist2(p, q)
                    if d in dists_to_p or d in dist_sets_final.get(q, set()):
                        ok = False
                        break
                    dists_to_p.append(d)
                if ok:
                    add_point(p, final, dist_sets_final)
        cleaned = [list(pt) for pt in final]

    return cleaned
